# Mesnevî, I. cilt: Tüccar ile papağan (eski ayrı “Tûtî ve Tüccar” kitabı buraya katıldı)
B=[('طوطی و بازرگان: بازرگان و طوطی', 'Tüccar ile papağan: Tüccar ve papağan', [('در شهری بزرگ بازرگانی ثروتمند زندگی می\u200cکرد.', 'Büyük bir şehirde zengin bir tüccar yaşıyordu.'), ('خانه\u200cاش بزرگ بود و باغی پر از گل داشت.', 'Evi büyüktü ve çiçeklerle dolu bir bahçesi vardı.'), ('در این خانه طوطی سبز و زیبایی در قفسی طلایی زندگی می\u200cکرد.', 'Bu evde yeşil ve güzel bir papağan altın bir kafeste yaşıyordu.'), ('طوطی خیلی باهوش بود و مثل آدم حرف می\u200cزد.', 'Papağan çok akıllıydı ve insan gibi konuşurdu.'), ('بازرگان طوطی را خیلی دوست داشت.', 'Tüccar papağanı çok severdi.'), ('هر روز به او شکر و دانه می\u200cداد و با او حرف می\u200cزد.', 'Her gün ona şeker ve tane verir, onunla konuşurdu.'), ('مهمان\u200cها از صدای خوش طوطی تعجب می\u200cکردند.', 'Misafirler papağanın güzel sesine şaşarlardı.'), ('اما طوطی همیشه از پشت میله\u200cهای قفس به آسمان نگاه می\u200cکرد.', 'Ama papağan her zaman kafesin parmaklıklarının arkasından gökyüzüne bakardı.')]), ('طوطی و بازرگان: سفر به هندوستان', 'Tüccar ile papağan: Hindistan yolculuğu', [('یک روز بازرگان تصمیم گرفت برای تجارت به هندوستان برود.', 'Bir gün tüccar ticaret için Hindistan’a gitmeye karar verdi.'), ('همه\u200cی خانواده و خدمتکاران را جمع کرد.', 'Bütün aileyi ve hizmetçileri topladı.'), ('گفت: «من به هند می\u200cروم. از آنجا چه هدیه\u200cای برای شما بیاورم؟»', 'Dedi ki: “Hindistan’a gidiyorum. Oradan size ne hediye getireyim?”'), ('زنش گفت: «برای من پارچه\u200cی ابریشمی بیاور.»', 'Karısı dedi ki: “Bana ipek kumaş getir.”'), ('پسرش گفت: «برای من یک شمشیر زیبا بیاور.»', 'Oğlu dedi ki: “Bana güzel bir kılıç getir.”'), ('دخترش گفت: «من دستبند طلا می\u200cخواهم.»', 'Kızı dedi ki: “Ben altın bilezik istiyorum.”'), ('خدمتکاران هم هر کدام چیزی خواستند.', 'Hizmetçiler de her biri bir şey istedi.'), ('بازرگان همه را در دفترش نوشت.', 'Tüccar hepsini defterine yazdı.')]), ('طوطی و بازرگان: پیام طوطی', 'Tüccar ile papağan: Papağanın mesajı', [('آخر سر بازرگان پیش قفس رفت و پرسید: «تو چه می\u200cخواهی، طوطی عزیزم؟»', 'En sonunda tüccar kafesin yanına gitti ve sordu: “Sen ne istersin, sevgili papağanım?”'), ('طوطی کمی ساکت ماند و بعد گفت: «من هدیه نمی\u200cخواهم.»', 'Papağan biraz sessiz kaldı ve sonra dedi ki: “Ben hediye istemiyorum.”'), ('«فقط یک پیام از من به طوطی\u200cهای هند برسان.»', '“Sadece benden Hindistan’ın papağanlarına bir mesaj ulaştır.”'), ('«وقتی در هند طوطی\u200cها را در درختان دیدی، سلام مرا به آنها بگو.»', '“Hindistan’da papağanları ağaçlarda gördüğünde onlara selamımı söyle.”'), ('«بگو: دوست شما در قفس است و دلش برای شما تنگ شده.»', '“De ki: Dostunuz kafeste ve sizi özledi.”'), ('«آیا رواست که شما در باغ آزاد باشید و من در زندان بمیرم؟»', '“Sizin bahçede özgür olmanız, benim ise zindanda ölmem reva mı?”'), ('«از آنها بپرس: راه نجات من چیست؟»', '“Onlara sor: Benim kurtuluş yolum nedir?”'), ('بازرگان خندید و گفت: «باشد، پیامت را می\u200cرسانم.»', 'Tüccar güldü ve dedi ki: “Peki, mesajını ulaştırırım.”')]), ('طوطی و بازرگان: راه دراز', 'Tüccar ile papağan: Uzun yol', [('بازرگان با کاروانی بزرگ راه افتاد.', 'Tüccar büyük bir kervanla yola çıktı.'), ('شترها بار سنگینی از پارچه و ادویه داشتند.', 'Develerin kumaş ve baharattan ağır bir yükü vardı.'), ('آنها از کوه\u200cها و بیابان\u200cهای زیادی گذشتند.', 'Birçok dağı ve çölü geçtiler.'), ('شب\u200cها زیر ستاره\u200cها می\u200cخوابیدند.', 'Geceleri yıldızların altında uyuyorlardı.'), ('بعضی روزها باد شدید می\u200cآمد و خاک همه جا را می\u200cپوشاند.', 'Bazı günler şiddetli rüzgâr esiyor ve toz her yeri kaplıyordu.'), ('بعد از دو ماه به رودخانه\u200cای بزرگ رسیدند.', 'İki ay sonra büyük bir ırmağa vardılar.'), ('با کشتی از رودخانه گذشتند و به هندوستان رسیدند.', 'Gemiyle ırmağı geçtiler ve Hindistan’a vardılar.'), ('هوا گرم بود و همه جا سبز و پر از درخت بود.', 'Hava sıcaktı ve her yer yeşil ve ağaçlarla doluydu.')]), ('طوطی و بازرگان: بازار هند', 'Tüccar ile papağan: Hindistan çarşısı', [('بازرگان به بازار بزرگ شهر رفت.', 'Tüccar şehrin büyük çarşısına gitti.'), ('بازار پر از رنگ و بو و صدا بود.', 'Çarşı renk, koku ve sesle doluydu.'), ('فروشندگان فلفل و دارچین و چای و سنگ\u200cهای قیمتی می\u200cفروختند.', 'Satıcılar biber, tarçın, çay ve değerli taşlar satıyordu.'), ('بازرگان کالاهایش را فروخت و سود زیادی برد.', 'Tüccar mallarını sattı ve çok kâr etti.'), ('بعد هدیه\u200cها را یکی یکی خرید.', 'Sonra hediyeleri birer birer satın aldı.'), ('پارچه\u200cی ابریشمی برای زنش، شمشیر برای پسرش، دستبند برای دخترش.', 'Karısı için ipek kumaş, oğlu için kılıç, kızı için bilezik.'), ('خوشحال بود و به خانه فکر می\u200cکرد.', 'Mutluydu ve evi düşünüyordu.'), ('ناگهان پیام طوطی یادش آمد.', 'Birden papağanın mesajı aklına geldi.')]), ('طوطی و بازرگان: طوطی\u200cهای جنگل', 'Tüccar ile papağan: Ormanın papağanları', [('بازرگان از شهر بیرون رفت و به جنگلی رسید.', 'Tüccar şehirden çıktı ve bir ormana vardı.'), ('روی شاخه\u200cهای درختان صدها طوطی سبز نشسته بودند.', 'Ağaçların dallarında yüzlerce yeşil papağan oturuyordu.'), ('آنها آزادانه از این درخت به آن درخت پرواز می\u200cکردند.', 'Özgürce bu ağaçtan o ağaca uçuyorlardı.'), ('بازرگان ایستاد و با صدای بلند گفت: «ای طوطی\u200cها، سلام!»', 'Tüccar durdu ve yüksek sesle dedi ki: “Ey papağanlar, selam!”'), ('«طوطی من در قفس است و به شما سلام می\u200cرساند.»', '“Benim papağanım kafeste ve size selam gönderiyor.”'), ('«می\u200cگوید: دلم برای شما تنگ است؛ راه نجات من چیست؟»', '“Diyor ki: Sizi özledim; benim kurtuluş yolum nedir?”'), ('هنوز حرفش تمام نشده بود که اتفاق عجیبی افتاد.', 'Daha sözü bitmemişti ki tuhaf bir şey oldu.')]), ('طوطی و بازرگان: طوطی افتاد', 'Tüccar ile papağan: Papağan düştü', [('یکی از طوطی\u200cها شروع کرد به لرزیدن.', 'Papağanlardan biri titremeye başladı.'), ('بعد از شاخه افتاد و روی زمین بی\u200cحرکت ماند.', 'Sonra daldan düştü ve yerde hareketsiz kaldı.'), ('بازرگان ترسید و پشیمان شد.', 'Tüccar korktu ve pişman oldu.'), ('با خودش گفت: «وای! من این طوطی را کشتم!»', 'Kendi kendine dedi ki: “Eyvah! Bu papağanı ben öldürdüm!”'), ('«شاید این طوطی از خویشان طوطی من بود.»', '“Belki bu papağan benim papağanımın akrabalarındandı.”'), ('«چرا این پیام را رساندم؟ زبان من آتش است.»', '“Bu mesajı neden ulaştırdım? Dilim ateştir.”'), ('«حرفی که از دهان بیرون آمد، دیگر برنمی\u200cگردد.»', '“Ağızdan çıkan söz bir daha geri dönmez.”'), ('غمگین به شهر برگشت و چند روز با کسی حرف نزد.', 'Üzgün bir şekilde şehre döndü ve birkaç gün kimseyle konuşmadı.')]), ('طوطی و بازرگان: بازگشت', 'Tüccar ile papağan: Dönüş', [('سرانجام کار بازرگان در هند تمام شد.', 'Sonunda tüccarın Hindistan’daki işi bitti.'), ('او با کاروان به سوی خانه برگشت.', 'Kervanla eve doğru döndü.'), ('در راه همیشه به طوطی جنگل فکر می\u200cکرد.', 'Yolda hep ormandaki papağanı düşünüyordu.'), ('وقتی به شهر خود رسید، همه به استقبالش آمدند.', 'Kendi şehrine vardığında herkes onu karşılamaya geldi.'), ('هدیه\u200cها را به خانواده داد و همه خوشحال شدند.', 'Hediyeleri ailesine verdi ve herkes sevindi.'), ('پسرش شمشیر را بالا گرفت و دخترش دستبند را به دست کرد.', 'Oğlu kılıcı havaya kaldırdı, kızı da bileziği koluna taktı.'), ('اما بازرگان پیش قفس نرفت؛ از طوطی خجالت می\u200cکشید.', 'Ama tüccar kafesin yanına gitmedi; papağandan utanıyordu.')]), ('طوطی و بازرگان: سؤال طوطی', 'Tüccar ile papağan: Papağanın sorusu', [('شب، طوطی او را صدا زد: «ای صاحب من، چرا پیش من نمی\u200cآیی؟»', 'Gece papağan onu çağırdı: “Ey sahibim, neden yanıma gelmiyorsun?”'), ('«پیام مرا رساندی؟ طوطی\u200cهای هند چه گفتند؟»', '“Mesajımı ulaştırdın mı? Hindistan’ın papağanları ne dedi?”'), ('بازرگان آهی کشید و گفت: «کاش آن پیام را نمی\u200cرساندم.»', 'Tüccar iç çekti ve dedi ki: “Keşke o mesajı ulaştırmasaydım.”'), ('«وقتی پیامت را گفتم، یکی از آنها لرزید و از درخت افتاد و مرد.»', '“Mesajını söylediğimde içlerinden biri titredi, ağaçtan düştü ve öldü.”'), ('«من از گفتن آن پیام پشیمانم.»', '“O mesajı söylediğime pişmanım.”'), ('طوطی این را شنید و هیچ نگفت.', 'Papağan bunu duydu ve hiçbir şey demedi.'), ('ناگهان او هم لرزید و در قفس افتاد و بی\u200cحرکت ماند.', 'Birden o da titredi, kafesin içine düştü ve hareketsiz kaldı.')]), ('طوطی و بازرگان: غم بازرگان', 'Tüccar ile papağan: Tüccarın kederi', [('بازرگان فریاد زد و کلاهش را بر زمین زد.', 'Tüccar bağırdı ve şapkasını yere çarptı.'), ('«ای طوطی شیرین زبان من! ای همدم من!»', '“Ey tatlı dilli papağanım! Ey dert ortağım!”'), ('«چه کردم؟ با یک خبر دو طوطی را کشتم!»', '“Ne yaptım? Bir haberle iki papağanı öldürdüm!”'), ('همه\u200cی خانواده جمع شدند و گریه کردند.', 'Bütün aile toplandı ve ağladı.'), ('بازرگان در قفس را باز کرد.', 'Tüccar kafesin kapısını açtı.'), ('طوطی را آرام بیرون آورد و روی زمین گذاشت.', 'Papağanı yavaşça dışarı çıkardı ve yere koydu.'), ('گفت: «حالا دیگر قفس برای چه؟ بگذار آزاد باشد.»', 'Dedi ki: “Artık kafes ne işe yarar? Bırak özgür olsun.”')]), ('طوطی و بازرگان: پرواز', 'Tüccar ile papağan: Uçuş', [('در همان لحظه طوطی بال زد و پرید.', 'Tam o anda papağan kanat çırptı ve havalandı.'), ('روی بلندترین شاخه\u200cی درخت باغ نشست.', 'Bahçedeki ağacın en yüksek dalına kondu.'), ('بازرگان حیران ماند و گفت: «تو زنده\u200cای؟»', 'Tüccar şaşkın kaldı ve dedi ki: “Sen yaşıyor musun?”'), ('طوطی گفت: «آن طوطی هند نمرده بود.»', 'Papağan dedi ki: “Hindistan’daki o papağan ölmemişti.”'), ('«او با کارش به من درسی داد.»', '“Yaptığıyla bana bir ders verdi.”'), ('«گفت: تو را صدای خوشت در قفس نگه داشته است.»', '“Dedi ki: Seni kafeste tutan güzel sesindir.”'), ('«اگر آزادی می\u200cخواهی، بمیر پیش از آنکه بمیری.»', '“Özgürlük istiyorsan, ölmeden önce öl.”')]), ('طوطی و بازرگان: درس طوطی', 'Tüccar ile papağan: Papağanın dersi', [('بازرگان گفت: «این حرف یعنی چه؟»', 'Tüccar dedi ki: “Bu söz ne demek?”'), ('طوطی گفت: «یعنی از خودخواهی و هوس بگذر.»', 'Papağan dedi ki: “Yani bencillikten ve hevesten vazgeç.”'), ('«تا وقتی که به خودت و به تعریف مردم دلبسته\u200cای، در قفسی.»', '“Kendine ve insanların övgüsüne bağlı olduğun sürece kafestesin.”'), ('«قفس من از طلا بود، اما باز هم قفس بود.»', '“Benim kafesim altındandı ama yine de kafesti.”'), ('«حالا خداحافظ، ای صاحب مهربان من.»', '“Şimdi hoşça kal, ey iyi kalpli sahibim.”'), ('«تو هم روزی از قفس خودت آزاد شو.»', '“Sen de bir gün kendi kafesinden kurtul.”'), ('بعد پرواز کرد و در آسمان آبی ناپدید شد.', 'Sonra uçtu ve mavi gökyüzünde gözden kayboldu.')]), ('طوطی و بازرگان: سخن مولانا', 'Tüccar ile papağan: Mevlânâ’nın sözü', [('بازرگان مدتی زیر درخت نشست و فکر کرد.', 'Tüccar bir süre ağacın altında oturdu ve düşündü.'), ('فهمید که خودش هم در قفسی از مال و نام زندگی می\u200cکند.', 'Kendisinin de maldan ve şöhretten bir kafeste yaşadığını anladı.'), ('از آن روز به فقیران بیشتر کمک کرد.', 'O günden sonra fakirlere daha çok yardım etti.'), ('و کمتر به حرف مردم اهمیت داد.', 'Ve insanların sözüne daha az önem verdi.'), ('مولانا این داستان را در مثنوی آورده است.', 'Mevlânâ bu hikâyeyi Mesnevî’de anlatmıştır.'), ('در نظر او طوطی جان انسان است و قفس، دنیا.', 'Onun gözünde papağan insanın ruhudur, kafes de dünya.'), ('و هند، جای دوستانی است که جان از آنجا آمده است.', 'Hindistan da ruhun oradan geldiği dostların yeridir.')])]
